import Foundation

struct HelpTopic: Identifiable, Hashable {
    var id: String
    var category: String
    var title: String
    var symbol: String
    var summary: String
    var sections: [HelpSection]

    var searchableText: String {
        ([category, title, summary] + sections.flatMap { [$0.title, $0.body] }).joined(separator: " ")
    }
}

struct HelpSection: Hashable {
    var title: String
    var body: String
}

enum HelpContent {
    static let topics: [HelpTopic] = [
        HelpTopic(id: "basic-effects", category: "編集", title: "素材を動かす・震わせる", symbol: "waveform.path", summary: "立ち絵・画像・動画・字幕に動きや色の効果を追加します。", sections: [
            .init(title: "使い方", body: "タイムラインで素材を選択し、共通→エフェクト一覧→追加から「移動・拡大縮小」「振動」などを選びます。追加した行を選ぶと設定が表示されます。複数選択中もエフェクト一覧は主選択アイテムのみが対象です。"),
            .init(title: "移動と振動", body: "移動のX/Yは元の位置から画面幅・高さに対する割合、倍率は元の大きさに対する割合です。移動時間と等速／なめらかを選べます。振動は横・縦・角度の振幅と速さを設定します。pxは横1920pxの画面を基準に出力解像度へ比例します。変形効果が有効な間はプレビュー直接ドラッグを停止するため、基準位置は共通X/Yで調整してください。"),
            .init(title: "その他の効果", body: "連続回転、拡大縮小の繰り返し、なめらかな点滅、明るさ・コントラスト・彩度・色相、上下反転、モノクロ、白い光彩の発光、画面範囲の切り抜きに対応します。点滅の速さと濃度は控えめにしてください。"),
            .init(title: "保存と確認", body: "動画と同じ時刻で動きを描画します。チェックで有効／無効、上下ボタンで映像効果の処理順を変更できます。字幕装飾は映像効果より先に描画します。編集はUndo／Redoでき、プロジェクトに保存されます。1素材64件まで。移動は時間を過ぎると終了位置に止まります。分割・左端の長さ変更でも動きの経過時間を引き継ぎます。"),
            .init(title: "モザイクと制約", body: "モザイクのブロック幅は横1920px基準です。色調整とモザイクは高解像度・多数適用で描画負荷が増えます。クロマキー、任意形状マスク、自由な中間キーフレーム、映像速度変更・逆再生、エフェクトプリセット保存は未対応です。画面範囲の切り抜きは素材の外接枠ではなく画面端を基準にします。")
        ]),
        HelpTopic(id: "storyboard", category: "編集", title: "台本から絵コンテで編集する", symbol: "rectangle.grid.2x2", summary: "台詞1つを1コマにし、立ち絵の配置を前のコマから引き継ぎます。", sections: [
            .init(title: "シナリオを読み込む", body: "上部で「絵コンテ」を選び、「台本からコマを追加…」を押します。直接入力のほか、TXT、Markdown、CSV、TSV、JSONを読み込めます。TXTは「キャラクター管理の名前：セリフ」を1行ずつ記述します。CSV／JSONでは話者、セリフ、秒数を指定できます。最大300コマ、ファイルは2MBまでです。"),
            .init(title: "確認して反映", body: "読み込み後は、元の行番号、話者、セリフ、表示時間、立ち絵配置を一覧で確認します。未登録・重複した話者はオレンジ色で表示し、登録済みキャラクターを選ぶまで反映しません。既存コマへの追加と、既存コマを置き換える方法を選べます。反映は一回のUndoで戻せます。"),
            .init(title: "おすすめの編集補助AI", body: "確認画面で「このMac」または「リモートMac」を選び、「おすすめ配置をAIに依頼」を押すと、話者候補、表示時間、左右配置を提案します。ボタンを押した場合だけ、セリフ本文と登録キャラクター名を選択中のAIノードへ送ります。AIはセリフ本文と順番を変更しません。提案は一覧へ入るだけで、自動確定されません。"),
            .init(title: "AIへ絵コンテ情報を書き出す", body: "「AI情報を書き出す…」を押すと、現在のコマ、登録キャラクターと表情・プリセット、素材の名前と長さをJSONへ保存します。素材ファイル本体、Mac内の保存先、取り込み元プロファイル、接続トークンは含みません。ただし台詞やキャラクター名は含むため、外部サービスへ渡す前に内容を確認してください。JSON内のinstructionsをAIへ一緒に読ませ、proposalだけを編集させます。"),
            .init(title: "AI絵コンテを検証して仮組み", body: "AIから返されたJSONは「AI絵コンテJSONを読み込む…」で開きます。別プロジェクト・別シーン、未登録ID、不正な表情、重複配置、範囲外の座標や尺、300件超、4MB超のファイルは拒否します。読み込み後は追加・変更・削除・変更なしを一覧で確認し、「差分を適用して仮組み」を押した場合だけ字幕・立ち絵・生成済み音声へ反映します。台詞または話者を変えたコマの音声は未生成へ戻ります。全体を1回のUndoで戻せます。"),
            .init(title: "書き出し後に編集した場合", body: "JSONの書き出し後にプロジェクトが変わっている場合は古い情報として警告し、確認チェックを入れるまで適用できません。絵コンテ由来の項目をタイムライン側で変更している場合も、上書きを明示するまで仮組みできません。差分に意図しない削除や移動があればキャンセルし、最新情報を書き出してAIへ依頼し直してください。"),
            .init(title: "コマの調整", body: "コマを選ぶと右側で台詞・話者・長さを編集できます。前へ／次へ、複製、削除にも対応します。開始位置は最初にコマを追加したときの再生位置、初期の長さは3秒です。音声を生成または取り込むと音声長に合わせます。"),
            .init(title: "配置の継承と滑らかな移動", body: "話者は登場したコマ以降も画面に残ります。「配置する素材」でX/Y・拡大率・左右反転・表示・表情を変更すると、次の明示指定まで引き継ぎます。「前のコマから滑らかに移動」を有効にすると位置・拡大率を指定時間で滑らかに変えます。初登場・表示切替・左右反転・表情は即時切替です。停止中の調整画面はコマ末尾の状態です。「このコマから再生」で動きを確認してください。同じ動きが動画出力にも反映されます。既存のコマは有効にするまで即時切替を維持します。"),
            .init(title: "音声", body: "キャラクター管理でVOICEVOX、A.I.VOICE2、AquesTalk Player、またはMac音声の話者と初期値を設定すると、各コマの生成ボタンが使用方式に切り替わります。AquesTalk Playerは公式Mac版のインストールと利用条件の確認が必要です。Mac音声は別アプリ・別PC・接続設定なしで生成できます。A.I.VOICE2の直接生成にはmacOSのアクセシビリティ許可が必要です。作成済みの音声は「WAVをこのコマに追加…」でも取り込めます。"),
            .init(title: "タイムラインとの関係", body: "コマの編集は実際の字幕・立ち絵・音声へ反映され、通常の再生・動画出力が使えます。絵コンテ由来の項目をタイムラインで変更した場合は、上書き確認まで絵コンテ編集を止めます。その他の素材は上書きしません。保存・Undoに対応します。既存タイムラインを自動で絵コンテへ変換する機能はありません。")
        ]),
        HelpTopic(id: "ai-storyboard-exchange", category: "AI連携", title: "AI絵コンテJSONで仮組みする", symbol: "rectangle.2.swap", summary: "現在の編集情報をAIへ渡し、返された絵コンテ案を検証・差分確認して安全に仮組みします。", sections: [
            .init(title: "全体の流れ", body: "上部の編集モードを「絵コンテ」に切り替えます。「AI情報を書き出す…」でJSONを保存し、利用するAIへ渡します。AIが編集したJSONを「AI絵コンテJSONを読み込む…」で開き、差分を確認してから「差分を適用して仮組み」を押します。JSONを開いただけではプロジェクトは変更されません。"),
            .init(title: "書き出される情報", body: "現在のコマ順、話者、台詞、フレーム単位の長さ、キャラクターの位置・大きさ・左右反転・表示状態・表情を出力します。登録キャラクター、利用可能な表情とプリセット、音声設定の名前、素材の表示名・種類・長さもAIの判断材料として含みます。素材ファイル本体、画像、音声、Mac内の保存先、取り込み元プロファイル、接続先、接続トークンは含みません。"),
            .init(title: "AIへの依頼方法", body: "JSONファイルと一緒に「JSON内のinstructionsに従い、currentStoryboardを参考にproposalだけを編集してください。既存コマのsourceCardIDは維持し、新規コマはnullにしてください」と依頼します。希望する動画の長さ、雰囲気、話者、立ち位置、表情、残したい台詞も文章で伝えます。AIにはformat、schemaVersion、source、characters、assets、currentStoryboardを変更させないでください。"),
            .init(title: "配置とコマの規則", body: "proposal.cardsの並びが再生順です。既存コマを削除する場合はproposalから除き、追加する場合はsourceCardIDをnullにします。placementsに書かなかったキャラクターは前コマの配置を引き継ぎます。画面中心はX=0、Y=0です。X/Yは-2〜2、拡大率は0.05〜5、1コマは1フレーム以上10分以内です。表情・話者・キャラクターには書き出されたIDだけを使用します。"),
            .init(title: "読み込み時の安全確認", body: "最大4MB・300コマまで読み込めます。形式とバージョン、元プロジェクトとシーン、登録済みID、表情の所属、重複、台詞、尺、移動時間、座標、拡大率、有限の数値かを検証します。未知のIDや範囲外の値を含むJSONはプロジェクトへ反映せず、理由を表示します。JSON内に未知の命令やファイルパスが書かれていても実行しません。"),
            .init(title: "差分画面の見方", body: "「追加」は新しいコマ、「変更」は台詞・話者・尺・順番・配置・表情の変更、「削除」は現在のコマから消えるもの、「変更なし」は同じ内容です。AIの判断理由がnoteにあれば各行に表示します。意図しない削除や並べ替えがある場合はキャンセルし、proposalを修正するか最新のAI情報を書き出し直してください。"),
            .init(title: "古い情報とタイムライン競合", body: "書き出し後にプロジェクトが変わると「古い書き出し元」として警告します。内容を確認したチェックを入れるまで適用できません。絵コンテ由来の項目をタイムラインで直接編集している場合も、上書きを明示するまで適用できません。通常の動画・画像など、絵コンテが管理していない項目は削除しません。"),
            .init(title: "仮組みされる内容", body: "確認後は字幕と立ち絵を再構築し、変更していないコマの生成済み音声を維持します。台詞または話者を変えたコマと新規コマは、誤った声を使わないよう音声未生成になります。必要なコマで音声を生成し、口パク・表情・位置・字幕を再生確認してください。仮組み全体はCommand+Zの1回で元へ戻せます。"),
            .init(title: "外部AIへ渡す前の注意", body: "JSONには台詞、キャラクター名、表情名、プリセット名、素材の表示名が含まれます。個人情報、未公開情報、第三者へ送れない台詞や素材名がないか確認してください。アプリはJSONを外部へ自動送信しません。利用するAIサービスの保存方針は利用者自身で確認してください。")
        ]),
        HelpTopic(id: "character-voice-presets", category: "キャラクター", title: "素材と音声をプリセットで組み合わせる", symbol: "person.crop.rectangle.stack", summary: "使用ソフト・話者・スタイルを保存し、デフォルトの立ち絵を横で確認します。", sections: [
            .init(title: "音声の指定", body: "キャラクター管理で「音声ソフト・話者」を開き、VOICEVOX、A.I.VOICE2、AquesTalk Player、またはMac音声を選びます。AquesTalk Playerでは正確なプリセット名を、Mac音声ではこのMacに入っている日本語音声を保存します。候補を試聴し、キャラクターごとに設定してください。"),
            .init(title: "プリセット", body: "下の「キャラクタープリセット」で保存すると、音声ソフト・話者・スタイルと設定値も保存されます。適用すると音声パネルも指定に従います。話者やスタイルが見つからなければ自動で他の話者へ置き換えません。古いプリセットには音声情報がないため現在の音声指定を維持します。"),
            .init(title: "立ち絵の確認", body: "管理画面の右側はプレビュー専用です。「保存済みデフォルトを表示」で基準状態を確認できます。PSDレビュアーではPSD本来の階層・表示状態・上から下の重なり順を保持し、編集中のレイヤーと保存済みデフォルトを並べて比較できます。手動で並べ替えた後は「PSDの元順に戻す」で復元できます。以前に登録したPSDは「再読み込み」で順序情報を更新してください。境界線をドラッグして表示幅を調整できます。"),
            .init(title: "PSDから口パク・目パチを設定", body: "PSD形式のキャラクターは読み込み直後の口パク・目パチを空のまま保持します。キャラクター管理の「目パチ・口パクを自動設定」を押すと、PSDの階層と一般的なレイヤー名を調べ、検出できた中間コマを含む推奨設定をまとめて作成します。白目と黒目が別レイヤーの素材も1枚の開き目として合成します。自動判定できない素材や別の表情を使いたい場合は、各画像枠を押してPSDレイヤー選択画面から手動で割り当ててください。口は左から閉→開、目は左から開→閉の順です。「枠を追加」で中間画像を増やすと、プレビューと動画出力の両方で中間フレームを使って滑らかに動きます。割り当て後は元PSDの口・目フォルダーを基準画像から自動的に除外するため、初期パーツが下に残りません。設定はプロジェクトとキャラクタープリセットに保存されます。"),
            .init(title: "A.I.VOICE2の読取と直接生成", body: "起動後、アクセシビリティで明確に公開された話者とスタイルだけを読み取ります。ボイスムービースタジオのアクセシビリティ許可が必要です。話者・セリフ・音量・話速・高さ・抑揚・スタイルを一意に確認できた場合だけ製品画面へ設定し、WAVを書き出して音声・字幕・口パクを追加します。一覧や操作項目が読み取れない場合は、安全のため停止して画面を開き直す案内を表示します。")
        ]),
        HelpTopic(id: "external-voice", category: "音声", title: "A.I.VOICE2 の音声を使う", symbol: "waveform", summary: "製品を起動し、話者・抑揚・感情を設定してアプリ内から音声を生成できます。", sections: [
            .init(title: "直接生成", body: "音声パネルでA.I.VOICE2を選び、「起動して話者を読む」を押します。話者・セリフ・音量・話速・高さ・抑揚・感情スタイルを設定し、「この設定で試聴」または「生成してタイムラインに追加」を実行します。設定はキャラクターごとの初期値に保存できます。"),
            .init(title: "手動取り込み", body: "製品側で書き出した音声も「WAVを選択して追加…」から取り込めます。字幕が空欄なら同名の.txt（UTF-8またはShift-JIS）を読み込みます。30分・512MB以内のWAVに対応します。"),
            .init(title: "口パクと保存", body: "口パクは音量から推定し、無音では閉じます。音素解析ではありません。速度と目パチはキャラクター設定を使います。音声・字幕・立ち絵は一度のUndoで取り消せます。音声元を保存し、別の製品で誤って再生成しないようにします。"),
            .init(title: "監視フォルダー", body: "指定先の直下に追加・更新されたWAVを検出し、一覧の「追加」で現在の再生位置へ挿入します。監視開始前のファイルは検出しません。書き出し完了後に追加してください。製品の切替・画面を閉じる・アプリ終了で監視は停止します。"),
            .init(title: "安全な操作と初回設定", body: "直接生成は製品がmacOSへ公開するアクセシビリティ項目だけを使用し、固定座標や非公開APIには依存しません。初回はシステム設定の「プライバシーとセキュリティ → アクセシビリティ」でボイスムービースタジオを許可してください。製品更新などで項目を一意に特定できない場合は処理を止め、手動WAV取り込みを利用できます。")
        ]),
        HelpTopic(id: "mac-system-voice", category: "音声", title: "Macだけで霊夢・魔理沙向けの声を使う", symbol: "laptopcomputer", summary: "Mac標準の日本語音声からキャラクター向け初期候補を選び、音声・字幕・口パクを作成します。", sections: [
            .init(title: "必要なもの", body: "macOS 14以降の日本語システム音声を使用します。別のPC、接続先、トークン、音声合成アプリは不要です。日本語音声が一覧にない場合は、macOSのシステム設定で日本語音声を追加してからボイスムービースタジオを開き直してください。"),
            .init(title: "霊夢向け・魔理沙向け", body: "「霊夢向け」と「魔理沙向け」は、このMacに入っている日本語音声から異なる声質と初期の高さ・話速を選ぶ補助プリセットです。霊夢向けはKyoko、魔理沙向けはReedを優先し、入っていない場合は利用可能な日本語音声を候補にします。特定の市販音源と同一の声ではないため、必ず試聴してください。"),
            .init(title: "キャラクターへ割り当てる", body: "キャラクター管理の「音声ソフト・話者」でMac音声を選び、「霊夢向け」または「魔理沙向け」を押します。必要なら日本語音声一覧から変更し、音量・話速・高さを調整して保存します。通常の音声パネル、絵コンテ、一括キャラクター変更、既存音声の再生成へ引き継がれます。"),
            .init(title: "生成と口パク", body: "音声パネルでMac音声を選び、セリフと日本語音声を指定して試聴します。生成するとWAV、字幕、音量解析による口パク付き立ち絵をまとめて追加します。生成はMac内で完結し、セリフを外部へ送信しません。"),
            .init(title: "利用条件", body: "生成音声の利用条件はmacOSと選択したシステム音声の条件、キャラクター素材の規約に従います。公開前に利用範囲とクレジット要否を確認し、キャラクターの利用条件・クレジット欄へ記録してください。")
        ]),
        HelpTopic(id: "aquestalk-player", category: "音声", title: "AquesTalk Playerを連携する", symbol: "waveform.badge.plus", summary: "公式Mac版をVMSから呼び出し、プリセットによるWAV生成と口パクを行います。", sections: [
            .init(title: "準備", body: "AQUEST公式サイトからMac版AquesTalk Playerを入手し、Applicationsへインストールします。VMSは公式アプリを同梱・再配布しません。音声パネルで「AquesTalk」を選ぶと通常のインストール先を自動検出し、別の場所にある場合だけ「場所を設定…」で指定できます。「AquesTalk Playerを起動」は起動済みのPlayerを前面へ表示し、ファイル選択画面は開きません。"),
            .init(title: "プリセット", body: "声種、速度、アクセントなどはAquesTalk Playerでプリセットとして作成します。VMSのプリセット名へ正確な名前を入力してください。空欄の場合はPlayerで最後に選択したプリセットを使用します。公式にプリセット一覧取得コマンドがないため、VMSは存在しない名前を推測しません。"),
            .init(title: "生成", body: "VMSは公式のコマンド実行機能でテキストとプリセット名を渡し、一時WAVを書き出します。生成後は音声、字幕、音量ベースの口パク付き立ち絵をタイムラインへ追加します。絵コンテ、一括変更、既存音声の再生成にも同じプリセットを使用します。"),
            .init(title: "利用条件", body: "AquesTalk Playerは個人かつ非営利の場合に限り無償です。収益化した動画、業務、個人事業、法人、学校・大学などでの利用にはAQUESTの使用ライセンスが必要です。条件は変更される場合があるため、出力前に公式ページを確認してください。"),
            .init(title: "ライセンス情報の扱い", body: "秘密のライセンスキーはAquesTalk Player側で設定します。VMSはキーを入力・保存・表示せず、プロジェクトやGitHubにも記録しません。受託制作などで公開用ライセンスIDの表示を求められる場合は、クレジット画面の専用欄へ公開用IDだけを入力できます。"),
            .init(title: "クレジットと動画出力", body: "AquesTalk Playerで作った音声がプロジェクトにある場合、クレジットへ音声合成元を自動追加し、動画出力画面にも利用条件を表示します。表示だけでライセンス取得を代替するものではありません。公開目的に合うライセンスを利用者自身で確認してください。")
        ]),
        HelpTopic(id: "voice-emotion", category: "音声", title: "音声の抑揚・感情を編集する", symbol: "waveform", summary: "対応スタイルの選択、抑揚・話速・高さの調整と試聴ができます。", sections: [
            .init(title: "新しい音声", body: "音声パネルで使用ソフトと話者を選び、抑揚・話速・高さ・対応する感情スタイルを設定します。試聴してからタイムラインへ追加でき、選択キャラクターの音声初期値として保存することもできます。"),
            .init(title: "感情について", body: "VOICEVOXはエンジンが返した話者スタイルを、A.I.VOICE2は現在の話者画面から明確に読み取れたスタイルと強さを使用します。喜怒哀楽すべてが使えるとは限りません。抑揚は声の高低の幅であり、感情の強さとは別の設定です。"),
            .init(title: "既存アイテム", body: "音声アイテムの詳細パネルでスタイル・抑揚を変更し、「この設定で再生成」を押します。連動する立ち絵と新しく追加した音声の字幕長も更新します。ロックされた連動アイテムがあれば反映しません。再生成の取り消しで元の音声ファイルに戻ります。")
