        HelpTopic(id: "voice", category: "音声", title: "音声とキャラクター", symbol: "waveform.and.mic", summary: "音声生成、字幕、口パク、聞こえない場合の確認方法です。", sections: [
            .init(title: "音声を作る", body: "音声エンジンを起動して接続し、キャラクターと声を選択して文章を入力します。「生成してタイムラインに追加」で音声・字幕・キャラクターが追加されます。"),
            .init(title: "声が聞こえない", body: "音声エンジンへの接続、音量、ミュート、再生位置、音声アイテムの長さを確認してください。"),
            .init(title: "キャラクターの位置", body: "プレビュー上のキャラクターを直接ドラッグできます。直接操作が無効な場合はツールバーの切り替えを有効にしてください。")
